+func TestKubernetesServiceListenAddr(t *testing.T) {
+	fileConfig, err := ReadConfig(bytes.NewBufferString(`proxy_service:
+  listen_addr: proxy.example.com:3023
+kubernetes_service:
+  enabled: yes
+  listen_addr: kube.example.com
+`))
+	if err != nil {
+		t.Fatal(err)
+	}
+	cfg := service.MakeDefaultConfig()
+	if err := ApplyFileConfig(fileConfig, cfg); err != nil {
+		t.Fatal(err)
+	}
+	if cfg.Kube.ListenAddr == nil || cfg.Kube.ListenAddr.String() != "kube.example.com:3026" {
+		t.Fatalf("Kubernetes service listen address = %v, want kube.example.com:3026", cfg.Kube.ListenAddr)
+	}
+}
